import sys
sys.path.insert(0, ".")
from duration import parse_duration as p

ok = {
    "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400, "1w2d3h4m5s": 788645,
    "1:02:03": 3723, "-45s": -45, "0": 0, "1:30": 90, "1:00:00": 3600,
    "90:00": 5400, "-1h": -3600, "-1:30": -90, "-0s": 0, "1.5m": 90,
    "0.1h": 360, "05m": 300, "1h 30m": 5400, "0h": 0, "-0": 0, "1w": 604800,
}
bad = [
    "", "   ", "-", "+1h", "5", "1.5", "00", ".5h", "5.h", "1 h", "1H", "30m1h",
    "1h1h", "1hh", "0.3s", "1h  30m", " -  1h", "- 1h", "--1h", "1:60", "1:5",
    "1:2:3", "1:30:60", "1:2:03", "1h:30m", "1.5.5h", "1x", "h", "1:30m", "1h,30m",
    "1١h", "1:02:03:04", "1.h", "1h\n30m", "1:30\n",
]
for k, v in ok.items():
    r = p(k)
    assert r == v and type(r) is int, (k, r, v)
for k in bad:
    try:
        r = p(k)
    except ValueError:
        continue
    raise AssertionError(f"accepted {k!r} -> {r}")
for k in [5, None, b"1h"]:
    try:
        p(k)
    except TypeError:
        continue
    raise AssertionError(f"no TypeError for {k!r}")
print("all checks passed:", len(ok), "valid,", len(bad), "invalid, type errors ok")
'
